-- =============================================================================
-- University of Nigeria, Nsukka — Faculty of Social Sciences — Philosophy
-- Course outlines transcribed from the Faculty of Social Sciences course
-- handbook (scanned copy), covering the Four-Year Standard Undergraduate
-- Programme in Philosophy: all four years, both semesters, including
-- required ancillary, general-studies and elective courses. The handbook
-- also prints a separate condensed "Three Year Programme" (for direct-entry
-- students covering the same courses); that duplicate table is not
-- transcribed separately since it repeats courses already captured here.
-- =============================================================================
-- Run in the Supabase SQL Editor. Safe to run more than once: existing rows
-- for this department are removed first, so it updates rather than duplicates.
--
-- SEMESTERS: the handbook explicitly labels every course "FIRST SEMESTER" or
-- "SECOND SEMESTER" in its programme-structure tables, so those stated values
-- are used directly — no guessing was needed here.
--
-- MISSING PAGES: the scan jumps from printed page 103 straight to printed
-- page 112 (Political Science begins there) — printed pages 104-111, which
-- in the original handbook would carry course descriptions for PHIL 224
-- onward through PHIL 482, were never captured in this scan (the same kind
-- of page gap seen elsewhere in this document, e.g. between Public
-- Administration and Religion and Cultural Studies). Those majors are
-- therefore included with their real code/title/units from the
-- programme-structure table but an empty description, rather than guessed.
--
-- Two course-description headings had a digit that didn't match its
-- structure-table listing: "PHIL 362" is titled "Philosophy of Development
-- II" in the structure table but "Political and Social Philosophy" on its
-- own description page — the description heading's title is used since it
-- is the fuller, more specific source. "PHIL 351/352: African Philosophy II"
-- is filed under 351, matching the structure table's clearer digit.
--
-- ANCILLARY/GSP/ELECTIVE COURSES FROM OTHER DEPARTMENTS: courses such as
-- SOC 1xx/2xx/3xx, PSY 101/103, GSP 1xx/2xx, ECON 101/102, GERM 101/102,
-- FREN 101/102, POL SC 101/211, MC 201/212/242/313, CS 101/304, ANTH 201/303,
-- REL 201/351 and ENG 131 appear in the Philosophy timetable but their own
-- descriptions are not printed in the Philosophy section of this document,
-- so they carry real code/title/units only, description left blank.
-- =============================================================================

delete from public.course_outlines
 where institution = 'University of Nigeria, Nsukka'
   and department = 'Philosophy';

insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level,
   semester, credit_units, description, topics, contributor_name)
values
  ('PHIL 101', 'Introduction to Philosophy I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '100 Level', 'first', 2, 'The nature and the principal branches of Philosophy: philosophical problems of other disciplines; introduction to African Philosophical Thought, Philosophical method; illustrations from the history of philosophy.', '["The nature and the principal branches of Philosophy", "Philosophical problems of other disciplines", "Introduction to African Philosophical Thought, Philosophical method", "Illustrations from the history of philosophy"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 121', 'Ethics I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '100 Level', 'first', 2, 'Concepts of morality and value; the nature of human acts; the human will, properties and consequences of human acts; the norm of ethic; rights and duties.', '["Concepts of morality and value", "The nature of human acts", "The human will, properties and consequences of human acts", "The norm of ethic; rights and duties"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 131', 'Introduction to Logic I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '100 Level', 'first', 2, 'The course is designed to expose students to the basic elements of Logic. The nature of logic; the laws of thought; the nature and types of judgments; the nature, principles of definition, the process of inference and deductive arguments as well as the nature and types of syllogism are examined.', '["The nature of logic; the laws of thought", "The nature and types of judgments", "The nature, principles of definition", "The process of inference and deductive arguments", "The nature and types of syllogism"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 141', 'History of Philosophy I (Ancient)', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '100 Level', 'first', 2, 'Entry Philosophical thought: Egypt, China, India, Persia. Greek philosophy; the Ionian and Ieatic schools; the Sophists; Socrates, Plato and the Academy, Aristotle and the Peripatetic school; the Stoics and Epicureans. Greece Jewish philosophy; Plotinus and Neo-Platonism; St. Augustine.', '["Entry Philosophical thought: Egypt, China, India, Persia", "Greek philosophy; the Ionian and Ieatic schools; the Sophists", "Socrates, Plato and the Academy, Aristotle and the Peripatetic school", "The Stoics and Epicureans", "Greece Jewish philosophy; Plotinus and Neo-Platonism; St. Augustine"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 102', 'Introduction to Philosophy II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '100 Level', 'second', 2, '', '[]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 104', 'History and Philosophy of Science', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '100 Level', 'second', 2, '', '[]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 132', 'Introduction to Logic II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '100 Level', 'second', 2, 'Introduction to logic I is a prerequisite for this course. More basic elements of logic are introduced to the student. The nature of truth and validity are examined. Induction and analogy are treated. Modern scientific method and psychological pitfalls in thinking are discussed.

Prerequisite: Phil 131', '["More basic elements of logic are introduced to the student", "The nature of truth and validity are examined", "Induction and analogy are treated", "Modern scientific method and psychological pitfalls in thinking are discussed"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 162', 'Introduction to Social and Political Philosophy', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '100 Level', 'second', 2, 'The course treats various theories about the state and its citizens. The nature of political obligation the ideal state.', '["The course treats various theories about the state and its citizens", "The nature of political obligation the ideal state"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 103', 'Philosophy and Logic', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '100 Level', 'first', 2, '', '[]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 211', 'Metaphysics I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '200 Level', 'first', 2, 'The nature the metaphysics; the problems of being ontology, causality and substance are studied.', '["The nature the metaphysics", "The problems of being ontology, causality and substance are studied"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 231', 'Epistemology I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '200 Level', 'first', 2, 'Philosophical problems concerning the nature, foundations and scope of knowledge are critically examined.', '["Philosophical problems concerning the nature, foundations and scope of knowledge are critically examined"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 241', 'History of Philosophy II (Medieval)', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '200 Level', 'first', 2, 'This treats earlier scholastics; St. Thomas Aquinas, Duns Scotus, Okham; the period of transition.', '["This treats earlier scholastics; St. Thomas Aquinas, Duns Scotus, Okham", "The period of transition"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 251', 'African Philosophy I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '200 Level', 'first', 2, 'Descriptive and analytic examination of African traditional thought, its world views and main characteristics (religious, moral, mythological etc). Elucidation of its ontological notions of force, being and spirit, and cosmological notions (life, death, mystical power destiny, nature, etc). Institutional devices embodying African traditional thought; relation of this thought to its environment.', '["Descriptive and analytic examination of African traditional thought, its world views and main characteristics", "Elucidation of its ontological notions of force, being and spirit, and cosmological notions", "Institutional devices embodying African traditional thought; relation of this thought to its environment"]'::jsonb, 'Department of Philosophy handbook'),
