  ('PHIL 232', 'Symbolic Logic', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '200 Level', 'second', 2, 'This is a study of value of logical symbols; argument forms and arguments; statement forms; prepositional functions and quantifications; paradoxes of material implication; the three "Laws of Thought."', '["This is a study of value of logical symbols; argument forms and arguments", "Statement forms; prepositional functions and quantifications", "Paradoxes of material implication; the three \"Laws of Thought\""]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 234', 'Philosophy of Education', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '200 Level', 'second', 2, 'The need of a philosophy of education. Its aim; the process of education; the educated and educed; freedom and authority in education; curriculum and methods; who controls education.', '["The need of a philosophy of education. Its aim; the process of education", "The educated and educed; freedom and authority in education", "Curriculum and methods; who controls education"]'::jsonb, 'Department of Philosophy handbook'),
