  ('PHIL 323', 'Aesthetics', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '300 Level', 'first', 2, 'Classical and Modern Theories of art, beauty, and aesthetic judgment. The origins of artistic creations, the form or structure of artistic works, the function of art, and the problem of meaning in aesthetic judgments.', '["Classical and Modern Theories of art, beauty, and aesthetic judgment", "The origins of artistic creations, the form or structure of artistic works", "The function of art, and the problem of meaning in aesthetic judgments"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 325', 'Business Ethics', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '300 Level', 'first', 2, '', '[]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 343', 'History of Philosophy III (Modern)', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '300 Level', 'first', 2, 'Descartes to Hegel; beginning of the contemporary period.', '["Descartes to Hegel; beginning of the contemporary period"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 351', 'African Philosophy II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '300 Level', 'first', 2, 'Critical examination of the background of contemporary African thought, or urban culture on traditional thought. The quest for identity and pan-Africanism, nationalism, emergency of social philosophies (negritude, African socialism, communalism, etc); Independence and the transition; the drive towards positivism. The works and lives of Senghor, Nkrumah and Azikiwe may be used as case studies.', '["Critical examination of the background of contemporary African thought, or urban culture on traditional thought", "The quest for identity and pan-Africanism, nationalism, emergency of social philosophies (negritude, African socialism, communalism, etc)", "Independence and the transition; the drive towards positivism", "The works and lives of Senghor, Nkrumah and Azikiwe may be used as case studies"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 312', 'Philosophy of Religion I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '300 Level', 'second', 2, 'The main divisions of philosophical theology; attempts to prove or disprove the reality of God: religion and morality; religious language, special problems (miracles, magic and superstition, etc) are treated.', '["The main divisions of philosophical theology; attempts to prove or disprove the reality of God: religion and morality", "Religious language, special problems (miracles, magic and superstition, etc) are treated"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 332', 'Research Methodology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '300 Level', 'second', 2, '', '[]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 334', 'Epistemology II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '300 Level', 'second', 2, 'A detailed study of selected areas, topics or figures in Epistemology such as: the oriented Rationalists (Descartes, Leibniz, Spinoza). British Empiricists (Locke, Hume, Berkley) and recent contribution to the theory of knowledge.', '["A detailed study of selected areas, topics or figures in Epistemology", "The oriented Rationalists (Descartes, Leibniz, Spinoza)", "British Empiricists (Locke, Hume, Berkley) and recent contribution to the theory of knowledge"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 336', 'Marxist Philosophy', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '300 Level', 'second', 2, 'This is a study of selected works of Karl Marx with particular attention to their development and influence on African and other third world countries.', '["This is a study of selected works of Karl Marx with particular attention to their development and influence on African and other third world countries"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 346', 'Philosophy of Mathematics', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '300 Level', 'second', 2, '', '[]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 362', 'Political and Social Philosophy', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '300 Level', 'second', 2, 'Important theories of the States (naturalists, Hobbesian, Idealist, Marxist etc) and relate to conditions out of which they grew.', '["Important theories of the States (naturalists, Hobbesian, Idealist, Marxist etc) and relate to conditions out of which they grew"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 364', 'Philosophy of Logic', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '300 Level', 'second', 2, 'The nature of truth, probability and necessity; The status of logical laws; universals.', '["The nature of truth, probability and necessity", "The status of logical laws; universals"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 338', 'Philosophy of Technology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '300 Level', 'second', 2, '', '[]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 411', 'Philosophy of Mind I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '400 Level', 'first', 3, 'Materialist theories of mind; dualist theories; classical problems in philosophical psychology (e.g. personal identity, disembodied existence, etc).', '["Materialist theories of mind; dualist theories", "Classical problems in philosophical psychology (e.g. personal identity, disembodied existence, etc)"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 421', 'Contemporary Issues in Ethics', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '400 Level', 'first', 3, 'Topics in current moral debates of particular relevance and interest to Africa and Nigeria e.g. technology Transfer, capital punishment etc. This course also includes advanced study of selected areas in moral philosophy.', '["Topics in current moral debates of particular relevance and interest to Africa and Nigeria e.g. technology Transfer, capital punishment etc", "This course also includes advanced study of selected areas in moral philosophy"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 441', 'Oriental Philosophy', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '400 Level', 'first', 2, '', '[]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 443', 'Islamic Philosophy', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '400 Level', 'first', 2, 'The historical background of the philosophy in Islam; the translators and the first sects. Al-Farabi, Ibn Sina, Al-Ghazali, Ibn Rushd, faith and reason in Islam; sufism.', '["The historical background of the philosophy in Islam; the translators and the first sects", "Al-Farabi, Ibn Sina, Al-Ghazali, Ibn Rushd", "Faith and reason in Islam; sufism"]'::jsonb, 'Department of Philosophy handbook'),
