  ('PHIL 415', 'Philosophy of Religion II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '400 Level', 'first', 2, 'Further exploration of philosophical theology; theological reasoning and language; mysticism; symbolism and reductionism; immortality; the relationship of the study of important texts.', '["Further exploration of philosophical theology; theological reasoning and language", "Mysticism; symbolism and reductionism; immortality", "The relationship of the study of important texts"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 462', 'Gender Issues', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '400 Level', 'first', 2, '', '[]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 412', 'Philosophy of Mind II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '400 Level', 'second', 3, 'Further exploration of philosophical psychology, covering such topics as perception, personal identity and memory dreaming, motivation, the philosophical and psychological implication of cybernatics, concept formation.', '["Further exploration of philosophical psychology, covering such topics as perception, personal identity and memory dreaming, motivation", "The philosophical and psychological implication of cybernatics, concept formation"]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 432', 'Philosophy of Science', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '400 Level', 'second', 3, '', '[]'::jsonb, 'Department of Philosophy handbook'),
  ('PHIL 434', 'Philosophy of the Social Sciences', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Philosophy', '400 Level', 'second', 2, 'A philosophical inquiry into the methodology of the social science, and the problems encountered in the disciplines concerned with man and society. Topics to be discussed will include the meaning of causation, the problem of induction; the use and abuse of statistics; and the place of ideological models in social studies.', '["A philosophical inquiry into the methodology of the social science, and the problems encountered in the disciplines concerned with man and society", "The meaning of causation, the problem of induction", "The use and abuse of statistics; and the place of ideological models in social studies"]'::jsonb, 'Department of Philosophy handbook'),
